CREATE COLUMN TABLE "TEST_AP"."OTPA" ("AbsId" INTEGER CS_INT NOT NULL , "Code" NVARCHAR(8) NOT NULL , "Descr" NVARCHAR(30), "DataType" NVARCHAR(1) DEFAULT 'S', "FieldId" INTEGER CS_INT, "Locked" NVARCHAR(1) DEFAULT 'N', PRIMARY KEY ("AbsId")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OTPA_CODE" ON "TEST_AP"."OTPA" ( "Code" ASC )